questionvariables.text:
mean1:rand(101)+100;
aa:rand([-1,0,1]);
mean2:mean1+(rand(11)+10)*aa;
sd1:rand(5)+5;
bb:rand([1/3,1/2,1,2,3]);
sd2:sd1*bb
ds1:rand(70)+30;
ds2:ds1;
dun1:makelist(round(float(quantile_normal(rand(1.0),mean1,sd1))),i,1,ds1);
mdun1:float(mean(dun1));
r_mdun1:round(mdun1);
sddun1:round(float(std1(dun1)));
dorx1:sort(dun1);
dun2:makelist(round(float(quantile_normal(rand(1.0),mean2,sd2))),i,1,ds2);
mdun2:float(mean(dun2));
mdiff:float(mdun1-mdun2);
dun2: if aa =0 then dun2+mdiff else dun2;
mdun2:float(mean(dun2));
r_mdun2:round(mdun2);
sddun2:round(float(std1(dun2)));
dorx2:sort(dun2);

maxfreq1:0;
k:1;
for i:2 thru ds1 do if dorx1[i]=dorx1[i-1] then (k:k+1, if maxfreq1 < k then maxfreq1:k) else k:1;
maxfreq2:0;
k:1;
for i:2 thru ds2 do if dorx2[i]=dorx2[i-1] then (k:k+1, if maxfreq2 < k then maxfreq2:k) else k:1;

xmin:if dorx1[1]<=dorx2[1] then dorx1[1]-2 else dorx2[1]-2;
xmax:if dorx1[ds1]>=dorx2[ds2] then dorx1[ds1]+2+(dorx1[ds1]-dorx1[1])/1.5 else dorx2[ds2]+2+(dorx2[ds2]-dorx2[1])/1.5;
ymin:-4;
ymax: maxfreq1+maxfreq2+5;

j:1;
dory1:makelist(0,i,1,ds1);
dory1[1]:1+maxfreq2+3;
for i:2 thru ds1 do if dorx1[i]=dorx1[i-1] then (j:j+1, dory1[i]:j+maxfreq2+3) else (j:1, dory1[i]:j+maxfreq2+3);
j:1;
dory2:makelist(0,i,1,ds2);
dory2[1]:1;
for i:2 thru ds2 do if dorx2[i]=dorx2[i-1] then (j:j+1, dory2[i]:j) else (j:1, dory2[i]:j);

ranchoice1:random_permutation([[1,"Production line L1 tends to produce longer widgets than L2"],[2,"Production line L2 tends to produce longer widgets than L1"],[3,"Neither production line tends to produce longer widgets than the other one"]]);



ta1_c:if aa>0 then 2 elseif aa<0 then 1 else 3;
ta1:[[3, is(ta1_c=3), "Neither variety has consistently taller plants than the other one."],[1, is(ta1_c=1), "On average variety V1 has much taller plants than V2."], [2, is(ta1_c=2), "On average variety V2 has much taller plants than V1."]];

ta2_c:if aa>0 then 2 elseif aa<0 then 1 else 3;
ta2:[[3, is(ta2_c=3), "\\( \\text{centre}(V1) \\approx \\text{centre}(V2) \\) "],[1, is(ta2_c=1), "\\( \\text{centre}(V1) > \\text{centre}(V2) \\)"], [2, is(ta2_c=2), "\\( \\text{centre}(V1) < \\text{centre}(V2) \\)"]];

ma1:if mdun1<mdun2 then 2 elseif mdun1>mdun2 then 1;

ta3_c:if bb>1 then 2 elseif bb<1 then 1 else 3;
ta3:[[3, is(ta3_c=3), "There is not a large difference between the variability of the heights of both varieties."],[1, is(ta3_c=1), "Variety V1 has plants whose heights are more variable than V2."], [2, is(ta3_c=2), "Variety V2 has plants whose heights are more variable than V1."]];

ta4_c:if bb>1 then 2 elseif bb<1 then 1 else 3;
ta4:[[3, is(ta4_c=3), "\\( \\text{spread}(V1) \\approx \\text{spread}(V2) \\) "],[1, is(ta4_c=1), "\\( \\text{spread}(V1) > \\text{spread}(V2) \\)"], [2, is(ta4_c=2), "\\( \\text{spread}(V1) < \\text{spread}(V2) \\)"]];


sda1:if mdun1<mdun2 then 2 elseif mdun1>mdun2 then 1;
